def parse_json(s: str) -> object:
    """
    A finite state machine (FSM) based parser for JSON strings. It processes the input
    character by character while transitioning between states to handle strings, numbers, booleans,
    null, arrays, and objects.
    """

    class FSM:
        def __init__(self, s):
            self.s = s
            self.index = 0
            self.state = self.parse_whitespace

        def next_char(self):
            return self.s[self.index] if self.index < len(self.s) else None

        def advance(self):
            self.index += 1

        def error(self, message):
            raise ValueError(message)

        def parse_whitespace(self):
            while self.index < len(self.s) and self.s[self.index].isspace():
                self.advance()
            self.dispatch()

        def dispatch(self):
            char = self.next_char()
            if char == '"':
                self.state = self.parse_string
            elif char.isdigit() or char == '-':
                self.state = self.parse_number
            elif self.s[self.index:self.index + 4] == "true":
                self.advance(); self.advance(); self.advance(); self.advance()
                return True
            elif self.s[self.index:self.index + 5] == "false":
                self.advance(); self.advance(); self.advance(); self.advance(); self.advance()
                return False
            elif self.s[self.index:self.index + 4] == "null":
                self.advance(); self.advance(); self.advance(); self.advance()
                return None
            elif char == '[':
                self.state = self.parse_array
            elif char == '{':
                self.state = self.parse_object
            else:
                self.error(f"Unexpected character '{char}'")

            return self.state()

        def parse_string(self):
            self.advance()  # skip initial quote
            start_index = self.index
            while self.index < len(self.s):
                char = self.next_char()
                if char == '"':
                    result = self.s[start_index:self.index]
                    self.advance()  # skip closing quote
                    return result
                elif char == '\\':
                    self.advance()  # skip escape character
                    self.advance()  # skip the escaped character
                self.advance()
            self.error("Unterminated string")

        def parse_number(self):
            start_index = self.index
            if self.next_char() == '-':
                self.advance()
            if self.next_char() == '0':
                self.advance()
                if self.next_char() in '0123456789':
                    self.error("Invalid number format")
            else:
                while self.next_char() and self.next_char().isdigit():
                    self.advance()
            if self.next_char() == '.':
                self.advance()
                if not self.next_char().isdigit():
                    self.error("Invalid number format")
                while self.next_char() and self.next_char().isdigit():
                    self.advance()
            number = self.s[start_index:self.index]
            return float(number) if '.' in number else int(number)

        def parse_array(self):
            self.advance()  # skip '['
            array = []
            while self.index < len(self.s):
                self.state = self.parse_whitespace
                if self.next_char() == ']':
                    self.advance()  # skip ']'
                    return array
                array.append(self.dispatch())
                self.state = self.parse_whitespace
                if self.next_char() == ',':
                    self.advance()  # skip ','
                elif self.next_char() == ']':
                    self.advance()
                    return array
                else:
                    self.error("Expected ',' or ']' in array")

        def parse_object(self):
            self.advance()  # skip '{'
            obj = {}
            while self.index < len(self.s):
                self.state = self.parse_whitespace
                if self.next_char() == '}':
                    self.advance()  # skip '}'
                    return obj
                key = self.dispatch()
                self.state = self.parse_whitespace
                if self.next_char() != ':':
                    self.error("Expected ':' after key in object")
                self.advance()  # skip ':'
                value = self.dispatch()
                obj[key] = value
                self.state = self.parse_whitespace
                if self.next_char() == ',':
                    self.advance()  # skip ','
                elif self.next_char() == '}':
                    self.advance()  # skip '}'
                    return obj
                else:
                    self.error("Expected ',' or '}' in object")

    fsm = FSM(s)
    result = fsm.dispatch()
    if fsm.index != len(s):
        fsm.error("Extra data after JSON")
    return result

